rectangle &quot;🔴 **Није консулисано**\n215 линија (34%)&quot; as JAM #FFCDD2 {
  card &quot;P5 — Metrike
(49 linija)&quot; as J1
  card &quot;P6 — Детекција
(72 линија)&quot; as J2
