&lt;li&gt;&lt;a href=&quot;#_zašto_ne_source_sdkman_init_sh_u_zshenv&quot;&gt;Zašto ne &lt;code&gt;source sdkman-init.sh&lt;/code&gt; u .zshenv?&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
