&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_problem_zauzet_terminal&quot;&gt;Problem: zauzet terminal&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tri_neophodne_komande&quot;&gt;Tri neophodne komande&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ctrlz_zaustavi_sigtstp&quot;&gt;Ctrl+Z — Zaustavi (SIGTSTP)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fg_врати_на_предњи_план&quot;&gt;fg — Врати на предњи план&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bg_nastavi_u_pozadini&quot;&gt;bg — Nastavi u pozadini&lt;/a&gt;&lt;/li&gt;
