&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_научено_из_искуства&quot;&gt;Научено из искуства&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

rectangle &quot;**Локална инсталација**\n у домаћем директоријуму&quot; as install #LightGreen {
    card &quot;Nema sudo
 za modificiranje CSS/config&quot; as i1
    card &quot;opencode+LLM može\n sve izmeni&quot; as i2
    card &quot;Rollback = врати
 резерну копију са временом&quot; as i3
}

rectangle &quot;**Прилагођавање CSS**\n зум против font-size&quot; as css #LightYellow {
    card &quot;zoom &amp;gt; font-size
za listu komponenata&quot; as c1
    card &quot;Преопрег Layout JS
 висина/линијска висина&quot; as c2
    card &quot;Extension Custom CSS
 zahteva ručnu aktivaciju
 ручна (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;**Automatizacija**
 skript za ažuriranje&quot; as auto #LightCoral {
    card &quot;Ponovo ažurirajte CSS
nakon svakog ažuriranja&quot; as a1
    card &quot;Ukloniti checksums
 product.json&quot; as a2
    card &quot;Backup sa timestampom\n pre zamene&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

