&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arhitektonska_vizija&quot;&gt;Arhitektonska vizija&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_водостави_принцип&quot;&gt;Водостави принцип&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arhitektura se temeljí na principu &lt;strong&gt;odvajanje zabrinutosti&lt;/strong&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Sadržaj&lt;/strong&gt; : strukturirani AsciiDoc fajlovi sa bogatim metapodacima&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Презентација&lt;/strong&gt; : шаблоне Thymeleaf повтрно користиви&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Podaci&lt;/strong&gt; : model koji se automatski izvlači od JBake iz AsciiDoc atributa&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Стил&lt;/strong&gt; : Bootstrap 5 за визуалну консистентност&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_strategijski_izbor_asciidoc_za_portfolio&quot;&gt;Strategijski izbor: AsciiDoc za portfolio&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Зашто AsciiDoc?&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Критеријум&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;предност&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Konzistentnost&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Isti format kao članci na blogu&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;metapodaci&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Strukturirani i proširivi atributi (&lt;code&gt;project-*&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Održljivost&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Jednostavno uređivanje teksta, Git verzioniranje&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;fleksibilnost&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Можа садржати богато садржај (табеле, код, слике)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Шаблонирање&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake automatski izvuče atribute za Thymeleaf&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_model_podataka&quot;&gt;Model podataka&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Svaki portfolio projekat je dokument AsciiDoc sa:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Metapodaci zaglavlja&lt;/strong&gt;: strukturirane informacije (klijent, trajanje, tehnologije, itd.)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Тело документа&lt;/strong&gt; : narativni opis, izazovi, rešenja, rezultati&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Прилагођени атрибути&lt;/strong&gt; : префиксирани`project-*`за автоматско извлечење&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;projekat&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  --
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  --
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_detaljni_slučajevi_korišćenja&quot;&gt;Detaljni slučajevi korišćenja&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc1_dodati_element_u_portfelj&quot;&gt;UC1 : Dodati element u portfelj&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominalni_tok&quot;&gt;Nominalni tok&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Urednik
Tekst&quot; as editor
participant &quot;Фајл\nAsciiDoc&quot; as file
participant &quot;JBake\nmotor&quot; as jbake
participant &quot;Статички\nСајт&quot; as site

dev -&amp;gt; editor : Créer nouveau fichier
activate editor
editor -&amp;gt; file : portfolio/nouveau-projet.adoc
activate file

dev -&amp;gt; editor : Rédiger en-tête avec métadonnées\n(titre, type=project, status=published,\nattributs project-*)
dev -&amp;gt; editor : Rédiger contenu narratif\n(contexte, défis, solutions)
dev -&amp;gt; editor : Ajouter images dans assets/img/portfolio/

editor -&amp;gt; file : Sauvegarder
deactivate editor

dev -&amp;gt; jbake : Lancer build (jbake -b)
activate jbake
jbake -&amp;gt; file : Lire et parser
jbake -&amp;gt; jbake : Extraire métadonnées
jbake -&amp;gt; jbake : Convertir AsciiDoc → HTML
jbake -&amp;gt; jbake : Appliquer template project.html
jbake -&amp;gt; jbake : Ajouter à la liste portfolio.html
jbake -&amp;gt; site : Générer pages statiques
deactivate jbake

dev -&amp;gt; site : Vérifier résultat
activate site
site --&amp;gt; dev : Afficher projet
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_šablon_fajla_koji_se_kreira&quot;&gt;Šablon fajla koji se kreira&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Развојник создаје`content/portfolio/nom-projet.adoc`sa standardizovanom strukturom:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Naslov sa svim potrebnim atributima&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Normalizovane sekcije (Kontekst, Izazovi, Rešenja, Rezultati)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Koherentna nomenklatura slika&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_тачке_валидације&quot;&gt;тачке валидације&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Obavezni atributi su prisutni(&lt;code&gt;jbake-type&lt;/code&gt;, &lt;code&gt;jbake-status&lt;/code&gt;, &lt;code&gt;project-thumbnail&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Referencirane slike postoje u`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Build JBake uspešno se izvršava bez greške&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Пројекат се појављује на страници портфолио.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Individualna stranica projekta se prikazuje ispravno.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc2_уклони_елемент_из_портфолио&quot;&gt;UC2 : Уклони елемент из портфолио&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominalni_tok_2&quot;&gt;nominalni tok&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Sistem
Fajlovi&quot; as fs
participant &quot;JBake\nEngine&quot; as jbake
participant &quot;статични\nсајт&quot; as site
database &quot;keš
JBake&quot; as cache

dev -&amp;gt; fs : Supprimer portfolio/projet-ancien.adoc
activate fs
fs --&amp;gt; dev : Fichier supprimé
deactivate fs

dev -&amp;gt; fs : (Optionnel) Supprimer images associées\nassets/img/portfolio/projet-ancien-*
activate fs
fs --&amp;gt; dev : Images supprimées
deactivate fs

dev -&amp;gt; cache : Nettoyer cache JBake
activate cache
cache --&amp;gt; dev : Cache vidé
deactivate cache

dev -&amp;gt; jbake : Rebuild complet (jbake -b)
activate jbake
jbake -&amp;gt; jbake : Scanner content/portfolio/
jbake -&amp;gt; jbake : Projet absent → non généré
jbake -&amp;gt; jbake : Régénérer portfolio.html\n(sans le projet supprimé)
jbake -&amp;gt; site : Déployer nouveau build
deactivate jbake

dev -&amp;gt; site : Vérifier
activate site
site --&amp;gt; dev : Projet absent de la liste
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_alternativna_strategija_arhiviranje&quot;&gt;Alternativna strategija: arhiviranje&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Umesto trajnog brisanja, mogućnost kreiranja fascikle`content/portfolio/archive/`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Премести фајл уместо да га обришеш&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Omogućava lako vraćanje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zadrži istoriju Git jasnije&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_čišćenje_resursa&quot;&gt;Čišćenje resursa&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Проверити сиротске слике у`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Уклони слике не референциране од стране других пројеката&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Očistiti JBake keš da se izbegnu fantomske reference&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc3_postaviti_na_neobjavljeno_draft&quot;&gt;UC3 : Postaviti na neobjavljeno (draft)&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominalni_tok_3&quot;&gt;nominalni tok&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Фајл
AsciiDoc&quot; as file
participant &quot;JBake\nMotor&quot; as jbake
participant &quot;Статични
сајт&quot; as site

dev -&amp;gt; file : Ouvrir portfolio/projet.adoc
activate file

dev -&amp;gt; file : Modifier attribut\n:jbake-status: published\n↓\n:jbake-status: draft

file --&amp;gt; dev : Sauvegardé
deactivate file

dev -&amp;gt; jbake : Rebuild (jbake -b)
activate jbake
jbake -&amp;gt; file : Parser le fichier
jbake -&amp;gt; jbake : Détecter status=draft
jbake -&amp;gt; jbake : Exclure de published_projects
jbake -&amp;gt; jbake : Ne pas créer page publique
note right
  Le projet existe toujours
  mais n&#39;est pas publié
end note
jbake -&amp;gt; site : Générer site (sans ce projet)
deactivate jbake

dev -&amp;gt; site : Vérifier portfolio
activate site
site --&amp;gt; dev : Projet absent de la liste publique
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_moguća_stanja&quot;&gt;Moguća stanja&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

[*] --&amp;gt; Draft : Création initiale
Draft --&amp;gt; Published : Validation et publication
Published --&amp;gt; Draft : Retrait temporaire
Draft --&amp;gt; Archived : Projet abandonné
Published --&amp;gt; Archived : Projet obsolète
Archived --&amp;gt; [*] : Suppression définitive
Published --&amp;gt; Published : Mises à jour

note right of Draft
  :jbake-status: draft
  Non visible publiquement
  Utile pour projets en cours
end note

note right of Published
  :jbake-status: published
  Visible sur le portfolio
  Indexé par JBake
end note

note right of Archived
  Déplacé dans archive/
  ou jbake-status: archived
  Non publié mais conservé
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_tipični_slučajevi_upotrebe&quot;&gt;Tipični slučajevi upotrebe&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Projekt u izradi&lt;/strong&gt; : napraviti u draft, objaviti kad bude spreman&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Projet confidentiel temporairement&lt;/strong&gt; : пређи у чернови за време сагласња са клијентом&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Važno ažuriranje&lt;/strong&gt; : preći u draft, izmeniti, objaviti ponovo&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A/B testing&lt;/strong&gt;: duplikirati u draftu, testirati, objaviti najbolju verziju&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_архитектура_шаблонирања&quot;&gt;Архитектура шаблонирања&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_strategija_reutilizabilnih_template_a&quot;&gt;Strategija reutilizabilnih template-a&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Шаблони Thymeleaf&quot; {
  component [index.html] as index
  component [portfolio.html] as portfolio
  component [project.html] as project

  package &quot;delimični&quot; {
    component [header.html] as header
    component [footer.html] as footer
    component [project-card.html] as card
    component [tech-badge.html] as badge
    component [gallery.html] as gallery
  }
}

package &quot;Подаци JBake&quot; {
  database &quot;objavljeni_projekti&quot; as data
  database &quot;sadržaj (projekat)&quot; as content
}

index --&amp;gt; header
index --&amp;gt; footer

portfolio --&amp;gt; header
portfolio --&amp;gt; footer
portfolio --&amp;gt; card
data --&amp;gt; portfolio : itération

project --&amp;gt; header
project --&amp;gt; footer
project --&amp;gt; badge
project --&amp;gt; gallery
content --&amp;gt; project : projet individuel

note right of card
  Fragment réutilisable
  pour afficher une carte
  de projet avec :
  - thumbnail
  - titre
  - tags
  - highlights
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uzorak_izdvajanja_podataka&quot;&gt;Uzorak izdvajanja podataka&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake automatski transforma AsciiDoc attribusi u pristupačna svojstva u Thymeleaf:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Dokument AsciiDoc&quot; {
  (&quot;:project-client: Acme Corp&quot;) as attr1
  (&quot;:project-duration: 6 meseci&quot;) as attr2
  (&quot;:project-tags: java, react&quot;) as attr3
}

rectangle &quot;Model JBake&quot; {
  (content[&#39;project-client&#39;]) as prop1
  (content[&#39;project-duration&#39;]) as prop2
  (content.tags) as prop3
}

rectangle &quot;Šablon Thymeleaf&quot; {
  (th:text=&quot;${project[&#39;project-client&#39;]}&quot;) as tmpl1
  (th:text=&quot;${project[&#39;project-duration&#39;]}&quot;) as tmpl2
  (th:each=&quot;етикета : ${project.tags}&quot;) as tmpl3
}

attr1 --&amp;gt; prop1 : parsing
attr2 --&amp;gt; prop2 : parsing
attr3 --&amp;gt; prop3 : parsing

prop1 --&amp;gt; tmpl1 : binding
prop2 --&amp;gt; tmpl2 : binding
prop3 --&amp;gt; tmpl3 : binding
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_konvencije_imenovanja&quot;&gt;Konvencije imenovanja&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Atributi projekta&lt;/strong&gt; : префикс`project-*` (ex: &lt;code&gt;project-client&lt;/code&gt;, &lt;code&gt;project-tech-stack&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Datoteke&lt;/strong&gt; : kebab-case (primer:`ecommerce-platform.adoc`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Slike&lt;/strong&gt; : prefiks ime-projekat (primer:`ecommerce-platform-thumb.jpg`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Templates&lt;/strong&gt; : функционално име (ex:`project-card.html`, &lt;code&gt;tech-badge.html&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_radni_tok_publikacije&quot;&gt;radni tok publikacije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_цевовод_за_развој&quot;&gt;Цевовод за развој&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;projekat&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  __
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  __
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_okruženja&quot;&gt;okruženja&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Окружење&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;upotreba&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Prihvaćen statut&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;lokalno&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Razvoj i pregled&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;koncept, objavljeno&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;стадирање&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Validacija preproizvodnje&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;objavljeno samo&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Proizvodnja&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Javni sajt&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;objavljeno samo&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ekstenzibillost&quot;&gt;Ekstenzibillost&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_додавање_нових_атрибута&quot;&gt;Додавање нових атрибута&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da biste obogatili model podataka, jednostavno dodati nove prefiksirane atribute.&lt;code&gt;project-*&lt;/code&gt;(empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-awards&lt;/code&gt;: Nagrade i priznanja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-testimonial&lt;/code&gt;: Захватак клијента&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-team-size&lt;/code&gt;: Величина тима&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`project-budget-range`budžetski opseg&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovi atributi postaju automatski dostupni u šablonima bez modifikacije JBake motore.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_napredna_kategorizacija&quot;&gt;Napredna kategorizacija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

object Projet {
  project-category = &quot;веб&quot;
  project-subcategory = &quot;e-komercija&quot;
  project-industry = &quot;maloprodaja&quot;
  project-complexity = &quot;visok&quot;
}

object Taxonomie {
  categories : [web, mobile, data, devops]
  subcategories : Map&amp;lt;category, List&amp;gt;
  industries : [retail, finance, healthcare, ...]
  complexities : [low, medium, high]
}

Projet --&amp;gt; Taxonomie : classifié selon

note right of Taxonomie
  Permet filtrage multi-critères
  dans le template portfolio.html
  via JavaScript ou côté serveur
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_najbolje_prakse&quot;&gt;Najbolje prakse&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_organizacija_fajlova&quot;&gt;Organizacija fajlova&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Jedna datoteka = jedan projekat&lt;/strong&gt;: izbegnuti mešanje više projekata&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Сlike у посвећеном фолдеру&lt;/strong&gt;&lt;code&gt;assets/img/portfolio/nom-projet/&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Konzistentna nomenklatura&lt;/strong&gt; : olakošava pretragu i održavanje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Versioning Git&lt;/strong&gt; : potpuno praćenje promena&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_управљање_садржајем&quot;&gt;Управљање садржајем&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Podrazumevani status nacrta&lt;/strong&gt; : objaviti samo kada je spremno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Преглед пре издавања&lt;/strong&gt; : провјера квалитета и конфиденцијалности&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Пуне метаподатке&lt;/strong&gt; : попuniti све релевантна полиja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Bogati narativni sadržaj&lt;/strong&gt; : Ne ograničavajte se na metapodatke&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_performans&quot;&gt;performans&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Optimiziraj slike&lt;/strong&gt; : kompresija pre commit&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Пагинација ако је потребна&lt;/strong&gt; : ако &amp;gt;20 пројеката&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Učitavanje na zahtev&lt;/strong&gt; : slike galerija učitane na zahtev&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Keš pregledača&lt;/strong&gt; : odgovarajuća zaglavlja za assete&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak&quot;&gt;Zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova arhitektura omogućava:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Jednostavnost korišćenja&lt;/strong&gt; : dodati projekat = kreirati tekstualni fajl&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Fleksibilnost&lt;/strong&gt; : ekstenzibilan preko novih atributa&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Održivost&lt;/strong&gt; : odvajanje sadržaja i prezentacije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Trazibilnost&lt;/strong&gt; : kompletno Git verzioniranje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Automatizacija&lt;/strong&gt; : kontinuirana gradnja i implementacija moguća&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Izbor AsciiDoca osigurava doslednost sa ostalom delom sajta, a uz to pruža bogatstvo metapodataka potrebnih za profesionalni portfolio.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Vreme za čitanje : 12 minutes&lt;/div&gt;
&lt;p&gt;Umesto da birate između jednostavnosti Supabase i moći Spring Boot, zašto ne kombinirate oba ? Pronadite hibridnu arhitekturu koja iskorištava najbolje od svake tehnologije.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;тик&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_lažni_dilema_moderne_arhitekture&quot;&gt;Lažni dilema moderne arhitekture&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Когако се гради модерна апликација са статичним фронтендом, често се налазиш пред бинарни избор :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Уложити све у Backend-as-a-Service решење&lt;/strong&gt;(Supabase, Firebase) - jednostavno, ali ograničeno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Izgraditi kompletan backend&lt;/strong&gt;(Spring Boot, Node.js) - moćan ali kompleksan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ово избор је лажан дилемa. Хибрид архитектура предлаже трећи пут: &lt;strong&gt;користити сваку технологију тамо где је најбоља&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arhitektonska_vizija&quot;&gt;Arhitektonska vizija&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tradicionalna_arhitektura_monolitna&quot;&gt;Tradicionalna arhitektura : monolitna&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Tradicionalna arhitektura&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  component &quot;Monolični backend&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;База података&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U ovom pristupu, čak i najjednostavnije operacije (citanje članka, kreiranje komentara) moraju da prođu kroz vaš backend. Plaćate trošak složenosti već od prvog dana.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_baas_arhitektura_svaki_delegat&quot;&gt;BaaS arhitektura : svaki delegat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Čista BaaS arhitektura&quot; {
  actor Utilisateur as user
  component &quot;Фронтенд&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Na suprotnom, delegovanje svega BaaS-u je svodljivo na početku, ali brzo pokazuje svoje ograničenja kada poslovna logika postane kompleksnija.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_hibridna_arhitektura_odvajanje_odgovornosti&quot;&gt;Hibridna Arhitektura : Odvajanje Odgovornosti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Слој фронтенд&quot; {
  component &quot;statičan sajt JBake&quot; as frontend #SkyBlue
}

package &quot;Jednostavan Sloj (Supabase)&quot; #LightGreen {
  component &quot;Autentifikacija&quot; as auth
  component &quot;Osnovni CRUD&quot; as crud
  component &quot;Складиште фајлова&quot; as storage
  component &quot;Реално време&quot; as realtime
}

package &quot;Poslovni sloj (Spring Boot)&quot; #Coral {
  component &quot;Сложна логика&quot; as logic
  component &quot;оркестровање&quot; as orchestration
  component &quot;Planirani poslovi&quot; as jobs
  component &quot;Интеграције&quot; as integrations
}

database &quot;PostgreSQL podeljeno&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura jasno podeljuje odgovornosti po kompleksnosti i prirodi operacija.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_principi_dizajna&quot;&gt;Principi dizajna&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_princip_1_počinite_jednostavno_razvojajte_se_pametno&quot;&gt;Princip 1 : Počinite jednostavno, razvojajte se pametno.&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**Faza 1: MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;Faza 2 : Rast&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (опционно)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;Faza 3 : Skaliranje&quot; #LightCoral {
  component &quot;Саврешена архитектура&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ne izgradite Spring Boot ako vam nije potreban.&lt;/strong&gt;Počnite sa Supabase-om, dodajte Spring Boot kada je složenost opравдана.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_princip_2_razdvajanje_po_vrsti_operacije&quot;&gt;Princip 2: Razdvajanje po vrsti operacije&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_princip_3_jedinstveni_izvor_istine&quot;&gt;Princip 3: Jedinstveni izvor istine&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;Shema: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Shema: javno (podeljeno)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Shema: poslovni (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Koristeći istu instancu PostgreSQL, Supabase i Spring Boot rade na istim podacima bez kompleksne synchronizacije.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_orkestracija_tokova&quot;&gt;Orkestracija Tokova&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tok_1_centralizovana_autentifikacija&quot;&gt;Tok 1: Centralizovana autentifikacija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;korisnik&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Пријави се&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ključna tačka&lt;/strong&gt;: Jedan proces autentifikacije, jedan JWT, koji se može koristiti svuda.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tok_2_orkestracija_jednego_složenog_poslovnog_procesa&quot;&gt;Tok 2: Orkestracija jednego složenog poslovnog procesa&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Klijent&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase baza podataka&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;Служба инвентаризације&quot; as inventory
participant &quot;E‑mail servis&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Šta donosi Spring Boot&lt;/strong&gt;: Pouzdana orkestracija složenih procesa koja uključuje više sistema sa transakcionom garancijom.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tok_3_zakazani_poslovi_i_sinhronizacije&quot;&gt;Tok 3: Zakazani poslovi i sinhronizacije&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Rasporednik
(Spring Boot)&quot; as scheduler
participant &quot;Usluga izveštaja&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;Eksterni API&quot; as api
participant &quot;Usluga e-pošte&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Šta Spring Boot donosi&lt;/strong&gt;: Pouzdani zakazani poslovi sa upravljanjem stanjem, automatski ponovi i garantovano izvršenje.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_матрица_одлуке&quot;&gt;Матрица одлуке&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_koristiti_supabase&quot;&gt;Kada koristiti Supabase?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_koristiti_spring_boot&quot;&gt;Kada koristiti Spring Boot ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_примери_архитектуре_по_тип_пројекта&quot;&gt;Примери архитектуре по тип пројекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portfelj&quot;&gt;Blog / Portfelj&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Osobni blog - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Besplatan)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (Izborno)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (Izborno)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Пресуда&lt;/strong&gt;: 100% Supabase je više nego dovoljno.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_aplikacija&quot;&gt;SaaS aplikacija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;SaaS aplikacija - Hibridna arhitektura&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Spoljne usluge&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL Dijeljeno&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Пресуда&lt;/strong&gt;Potrebna je hibridna arhitektura. Supabase za najvažnije, Spring Boot za kritični deo (plaćanja, fakturisanja).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_e_komerc&quot;&gt;e-komerc&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;E-komercija - 70% Spring Boot&quot; {
  component &quot;Storefront (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (основна деловатност)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Интеграције&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (основна деловатност)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Verdict&lt;/strong&gt;: Spring Boot je neophodan. Supabase samo za autentifikaciju i katalog.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_strategija_progresivne_migracije&quot;&gt;Strategija progresivne migracije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_troškovi_i_operativna_razmatranja&quot;&gt;Troškovi i operativna razmatranja&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_трошкова&quot;&gt;Структура трошкова&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Procijenjeni mesečni troškovi&quot; {

  rectangle &quot;Faza MVP
(0-1000 users)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Faza rasta
(1k-10k korisnika)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Skala faze
(10k-100k korisnika)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Skala faze
(10k-100k korisnika)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_одговорности_оперативно&quot;&gt;Одговорности Оперативно&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Ko upravlja šta?&quot; {

  rectangle &quot;Управљање од стране Supabase (0 напора)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Upravljeno od GitHub (0 trudova)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;Za upravljanje (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;Za upravljanje (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak_savršeno_ravnoteža&quot;&gt;Zaključak: Savršeno ravnoteža&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura Supabase i Spring Boot nije kompromis, ona je&lt;strong&gt;синергија&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_principi_koje_treba_zapamtiti&quot;&gt;Principi koje treba zapamtiti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_izabrati_ovu_arhitekturu&quot;&gt;Kada izabrati ovu arhitekturu?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Ova arhitektura je idealna ako :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Желите да покренете брзо (MVP у данима, не у месецима)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ви очекујете растусложности послова&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Želite da smanjite početne troškove&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Volite PostgreSQL i želite jedini izvor istine&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vi volite Kotlin i korutine za poslovni kod&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vi želite da izbegnete sav vendor lock-in&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ova arhitektura NIJE primeredna ako:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Ваш пројекат је једноставан и остаће тако (лични блог → 100% Supabase довољно)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Већ имате установлен бек-енд стек који контролишете&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ви предпочитате традиционални монолит&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Treba vam .NET, Python ili drugi programski jezik za backend&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_konačna_opšta_vizija&quot;&gt;Konačna Opšta Vizija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;пуна хибридна архитектура&quot; {

  actor &quot;Korisnici&quot; as users

  rectangle &quot;Frontend (statički)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Jednostavan backend (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Poslovni backend (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
Jedinstveni izvor istine&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_najbolje_od_dva_sveta&quot;&gt;Najbolje od dva sveta&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova arhitektura vam daje :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Brzina Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Pokretanje u satima, ne u nedeljama&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;OAuth2 autentifikacija u nekoliko klikova&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Automatski generisani REST API-ji&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Нулова конфигурација сервера&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 Моћ Spring Boot-а&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin i koutine za elegantan asinhroni kod&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orkestracija složenih poslovnih procesa&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pouzdani zakazani poslovi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Garantovane ACID transakcije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Potpun Spring ekosistem&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 Progresivna ekonomija&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ za početak i validaciju&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Troškovi koji prate rast&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Никако претерено инжењерство&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 Arhitektonska fleksibilnost&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Progresivna migracija bez redesigna&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Dodavanje Spring Boot samo ako je potrebno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Nema potpunog vendor lock‑ina&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Evolutivna arhitektura&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_за_даље&quot;&gt;За даље&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_технички_ресурси&quot;&gt;Технички ресурси&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Документација Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Упутство за аутентификацију&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Bezbednost na nivou reda&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;Automatski generirani API-jevi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Документација Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot sa Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Koruotine i Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT resursni server&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dodatni članaci :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Zaštita API-ja uz JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimizacija performansi PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Obrazci progresivne migracije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Управљање грешкама у распређеној архитектури&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_реални_случајеви_коришћења&quot;&gt;Реални случајеви коришћења&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova hibridna arhitektura se uspešno koristi u :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: Аутентификација Supabase, фактурисање Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tržišta&lt;/strong&gt;: Каталог Supabase, трансакције Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Platforme sadržaja&lt;/strong&gt;: Članci Supabase, analitika Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Unutrašnji alati&lt;/strong&gt;: CRUD Supabase, radni tokovi Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_чек_лист_за_почетак&quot;&gt;Чек-лист за почетак&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 1 - Osnovi (Nedelja 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Kreiraj nalog Supabase - [ ] Konfigurisati projekat PostgreSQL - [ ] Активисати Auth (Google, GitHub) - [ ] Definisati inicijalnu šemu - [ ] Konfigurisati Row Level Security - [ ] Тестирај API-je из JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 2 - MVP (sedmica 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Implementirati glavne stranice - [ ] Интегровати OAuth2 аутентификацију - [ ] Kreirati obrasce CRUD - [ ] Konfigurisati Storage za fajlove - [ ] Deploy na GitHub Pages - [ ] Testirati u realnim uslovima&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 3 - Evolucija (Po potrebi)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifikovati potrebe za kompleksnom logikom - [ ] Kreirati Spring Boot projekat ako je potrebno - [ ] Konfigurisanje validacije JWT Supabase - [ ] Povezati se sa PostgreSQL Supabase - [ ] Migrirati kompleksne funkcionalnosti - [ ] Implementirati zakazane poslove - [ ] deployirati Spring Boot (Cloud Run, etc.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_anti_paterni_koje_treba_izbegnuti&quot;&gt;Anti-paterni koje treba izbegnuti&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ne činiti:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Duplirati podatke između Supabase i Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kreirati dve odvojene PostgreSQL baze&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Кодирај сам аутентификацију&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Korišćenje Spring Boot-a za jednostavan CRUD&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Prekomerno arhićevati od samog početka&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Игнориши Row Level Security Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Bolje uraditi :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Podeliti jedinou bazu podataka PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Neka Supabase rukuje autentifikacijom&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Користи Spring Boot само заради комплексност&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Početi jednostavno, razvijati se postepeno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Korišćenje prednosti svake tehnologije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zaštiti sa RLS na nivou baze podataka&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_perspektive_evolucije&quot;&gt;Perspektive evolucije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_додавање_нових_способности&quot;&gt;Додавање нових способности&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Savremena arhitektura&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Moguće evolucije&quot; #LightYellow {

  package &quot;Performans&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;мониторинг&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;funkcionalnosti&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_horizontalno_skaliranje&quot;&gt;Horizontalno skaliranje&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kada vaša aplikacija rast, hibridna arhitektura se prirodno skalira :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;scale automatski do miliona operacija&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas za čitanje performanse&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vraćanje u tačnom trenutku za bezbednost&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Više instanci iza load balancer-a&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Bezstanovički dizajn olakšava horizontalno skaliranje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes za orkestraciju ako je potrebno&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Particioniranje za velike tabele&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Konekcijski pool (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding je zaista potrebno (rijetko)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_svedočanstva_arhitektonska&quot;&gt;Svedočanstva arhitektonska&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_korisnika&quot;&gt;Startup SaaS (50k korisnika)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;__&lt;/em&gt; Pokrenuli smo 100% Supabase. Na 5k korisnika, dodali smo Spring Boot samo za Stripe fakturaciju i mesečne izveze. Godinu dana kasnije, 80% naših operacija uvek prolazi kroz Supabase. Spring Boot rukuje samo kritičnim delom. Ovo razdvajanje nam je omogućilo da se skaliramo bez preprojektovanja. (empty)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_platforma_e_učenja_10k_korisnika&quot;&gt;Platforma e-učenja (10k korisnika)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ OAuth2 autentifikacija Supabase nama je uštedela tri nedelje razvoja. Automatski generisani API-je upravljaju svim naшим katalogom kurseva. Spring Boot se koristi samo za PDF sertifikate i mejlove o napretku. Jednostavna, održiva, skalabilna arhitektura. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_b2b_tržište_3k_korisnika&quot;&gt;B2B tržište (3k korisnika)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;__&lt;/em&gt; Spring Boot upravlja transakcijama između kupovaca i prodavaca (kritično). Supabase upravlja sve ostalo: profili, realno-vremenska poruka, dokumenti. Fakt da dele isto PostgreSQL bazu sprečava nam bilo kakvu kompleksnu sinkronizaciju. Najbolji arhitektonski izbor koji smo učinili. (Note: No content to translate; output is empty.)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sinteza_jedna_moderna_architectureska_paradigma&quot;&gt;Sinteza : Jedna moderna architectureska paradigma&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura Supabase + Spring Boot predstavlja novi paradigam:&lt;strong&gt;arhitektonska specijalizacija&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Стара парадигма&quot; #LightCoral {
  card &quot;Све у Backendu&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;novi paradigam&quot; #LightGreen {
  card &quot;Supabase
(Удобност)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot
(Diferenciacija)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Osnovni princip:&lt;/strong&gt;Ne gradite ono što već postoji kao usluga. Fokusirajte se na ono što razlikuje vašu aplikaciju.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pravilo_8020&quot;&gt;Pravilo 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U većini aplikacija:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% операција&lt;/strong&gt;su standardni CRUD → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% operacija&lt;/strong&gt;захтевају пословну логику → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo prirodno pravilo opravdava hibridnu arhitekturu.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Distribucija operacija&quot; {

  rectangle &quot;80% - Standardne operacije&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Poslovna logika&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak_završni&quot;&gt;Zaključak završni&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura nije tehnički kompromis, to je&lt;strong&gt;стратешка одлука&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Omogućava vam da:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Покрени брзо са функционалним MVP&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Проверити ваше тржиште без тешког улагања&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Постепно развијај се када комплексност захтева&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Kontrolirati vaše troškove u svakom koraku&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Iskoristiti najbolje iz svake tehnologije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Izbeći prematurno prekompleksiranje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Sačuvati fleksibilnost za budućnost&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Она predstavlja:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Sačuvaj sve kod sekvence unutar obrnuti navodnici (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) tačno kao što je — nikad ne menjať sadržaj, razmak ili poziciju.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj tekst može biti fragment veće rečenice — prevedi fragment bez zahtevanja dodatnog konteksta. Izlazni tekst samo prevedeni tekst — bez objašnjenja, komentarika, uvođenja, alternativa, opcija. 🎯&lt;strong&gt;Pragmatizam&lt;/strong&gt;: Svaka tehnologija u kojoj izuzetno uspeva&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;вeloцитет&lt;/strong&gt;: Minimalno vreme ulaska na tržište&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;економија&lt;/strong&gt;: Troškovi usklađeni sa vrednošću&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;еволутивност&lt;/strong&gt;: Архитектура која расте заједом са вама&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;Robustnost&lt;/strong&gt;Испитане и пouждане услуге&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vaš_sledeći_korak&quot;&gt;Vaš sledeći korak&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ako vam ova arhitektura govori, ovde je gde da započnete :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kreirajte nalog Supabase&lt;/strong&gt;(besplatno)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Ваша минимална шема података&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Подесите OAuth2 аудентификацију&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kreirajte vašu prvu JBake stranicu koja konzumira API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Разместите на GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Imat ćete funkcionalni MVP u&lt;strong&gt;nekoliko dana&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot će doći naravno kada ga vi trebate. Ne prethodno.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Hibridna arhitektura je umetnost da se izgradi tačno ono što je potrebno, kada je potrebno.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dobrog razvoja! 🚀&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Поделите ваш članak ако мислите да може да помогне другим разработчицима дадонесу прави архитектонске одлуке.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;vreme za čitanje : 12 minutes&lt;/div&gt;
&lt;p&gt;Umesto da birate između prostote Supabase i moći Spring Boot, zašto ne kombinišete oba? Otkri hibridnu arhitekturu koja koristi najbolje iz svake tehnologije.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;тик&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_lažna_dilema_moderne_arhitekture&quot;&gt;Lažna Dilema Moderne Arhitekture&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pri izradi moderne aplikacije sa statičkim frontendom, često se suočavamo sa binarnim izborom:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Svesti se na rešenje Backend-as-a-Service&lt;/strong&gt;(Supabase, Firebase) - jednostavno, ali ograničeno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Izgraditi jedan kompletan backend&lt;/strong&gt;(Spring Boot, Node.js) - moćan ali kompleksan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj izbor je lažni dilema. Hibridna arhitektura nudi treći put: &lt;strong&gt;koristiti svaku tehnologiju tamo gde izvrsno funkcionise&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arhitektonska_vizija&quot;&gt;Arhitektonska vizija&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tradicionalna_arhitektura_monolitna&quot;&gt;Tradicionalna arhitektura: Monolitna&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;традиционална архитектура&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  component &quot;Monolitni backend&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;База података&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U ovom pristupu, čak i najjednostavnije operacije (čitanje članka, kreiranje komentara) moraju proći kroz vaš back‑end. Plaćate trošak kompleksnosti od prvog dana.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_baas_arhitektura_svaki_delegat&quot;&gt;BaaS arhitektura: Svaki delegat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Arhitektura BaaS čista&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naopako, sve delegiranje BaaS-u je na početku svodivo, ali brzo pokazuje svoje ograničenja kada se poslovna logika komplikuje.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_hibridna_arhitektura_razdvojenje_odgovornosti&quot;&gt;Hibridna arhitektura: razdvojenje odgovornosti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Prednji sloj&quot; {
  component &quot;Statički sajt JBake&quot; as frontend #SkyBlue
}

package &quot;Jednostavan sloj (Supabase)&quot; #LightGreen {
  component &quot;authentifikacija&quot; as auth
  component &quot;Основни CRUD&quot; as crud
  component &quot;Складиштење Фајлова&quot; as storage
  component &quot;Реално време&quot; as realtime
}

package &quot;Poslovni sloj (Spring Boot)&quot; #Coral {
  component &quot;Kompleksna Logika&quot; as logic
  component &quot;OrkeStracija&quot; as orchestration
  component &quot;zapplanirani jobovi&quot; as jobs
  component &quot;integracije&quot; as integrations
}

database &quot;PostgreSQL deljen&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura jasno razdvojuje odgovornosti po složenosti i prirodi operacija.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_principi_dizajna&quot;&gt;Principi dizajna&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_princip_1_početi_jednostavno_razvijati_se_inteligentno&quot;&gt;Princip 1: Početi jednostavno, razvijati se inteligentno&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**Фаза 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**Faza 2 : Rast**&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (opciono)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;Faza 3 : Scale&quot; #LightCoral {
  component &quot;Kompletna arhitektura&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ne gradite Spring Boot ako vam nije potreban.&lt;/strong&gt;Počnite sa Supabase, dodajte Spring Boot kada je to podloženo složnošću.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_принцип_2_раздељење_према_природи_операције&quot;&gt;Принцип 2 : Раздељење према природи операције&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_princip_3_jedini_izvor_istine&quot;&gt;Princip 3: Jedini izvor istine&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;Shema: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Šema: javno (podeljeno)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Shema: biznis (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Koristeći istu PostgreSQL instancu, Supabase i Spring Boot rade na istim podacima bez kompleksne sinhronizacije.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_orkestracija_tokova&quot;&gt;Orkestracija tokova&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tok_1_centralizovana_autentifikacija&quot;&gt;Tok 1: Centralizovana autentifikacija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Корисник&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Prijavi se&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ključna tačka&lt;/strong&gt;Jedan proces autentifikacije, jedan JWT, koji se može koristiti svugde.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_2_orchestracija_kompleksnog_poslovnog_procesa&quot;&gt;Flux 2 : Orchestracija kompleksnog poslovnog procesa&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Klijent&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase DB&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;Usluga inventarisanja&quot; as inventory
participant &quot;Servis e-pošte&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Šta Spring Boot donosi&lt;/strong&gt;Pouzdana orkestracija složenih procesa koji uključuju više sistema sa transakcionom garancijom.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tok_3_zakazani_poslovi_i_sinkronizacije&quot;&gt;Tok 3: Zakazani poslovi i sinkronizacije&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Scheduler\n(Spring Boot)&quot; as scheduler
participant &quot;Izveštajski Servis&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;vanjska API&quot; as api
participant &quot;Сервис е-поште&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Šta pruža Spring Boot&lt;/strong&gt;: Pouzdani zakazani poslovi sa upravljanjem stanjem, automatskim ponovnim pokretanjem i garantovanim izvršavanjem.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_matrica_odlucke&quot;&gt;Matrica odlucke&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_koristiti_supabase&quot;&gt;Kada koristiti Supabase?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_koristiti_spring_boot&quot;&gt;Kada koristiti Spring Boot?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_примери_архитектуре_према_типу_пројекта&quot;&gt;Примери архитектуре према типу пројекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portfelj&quot;&gt;Blog / Portfelj&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Osobni blog - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Besplatno)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (опционално)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (опционално)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;пресуда&lt;/strong&gt;: 100% Supabase je sasvim dovoljno.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_aplikacija&quot;&gt;SaaS aplikacija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;SaaS aplikacija - hibridna arhitektura&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Eksterne usluge&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL deljen&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Presuda&lt;/strong&gt;: Hibridna arhitektura je potrebna. Supabase za osnovno, Spring Boot za kritični deo (plaćanja, fakturiranje).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_e_trgovina&quot;&gt;e-trgovina&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;E-trgovina - 70% Spring Boot&quot; {
  component &quot;Витрина (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (Основни пословни део)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Integracije&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (Основни пословни део)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;пресуда&lt;/strong&gt;Spring Boot neophodan. Supabase samo za auth i katalog.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_strategija_progresivne_migracije&quot;&gt;Strategija progresivne migracije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_troškovi_i_operativna_razmatranja&quot;&gt;Troškovi i operativna razmatranja&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_трошкова&quot;&gt;Структура трошкова&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Procenjeni mesečni troškovi&quot; {

  rectangle &quot;Faza MVP\n(0-1000 korisnika)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Faza Rasta\n(1k-10k korisnici)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Skala faze
(10k-100k korisnika)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Skala faze
(10k-100k korisnika)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_operativne_odgovornosti&quot;&gt;Operativne odgovornosti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Ko šta upravlja ?&quot; {

  rectangle &quot;Upravlja Supabase (0 napora)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Upravlja GitHub (0 napora)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;Да се управља (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;Да се управља (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak_savršeno_ravnoteža&quot;&gt;Zaključak : Savršeno ravnoteža&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura Supabase + Spring Boot nije kompromis, to je&lt;strong&gt;синергија&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_principi_koje_treba_zapamtiti&quot;&gt;Principi koje treba zapamtiti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kada_odabrati_ovu_arhitekturu&quot;&gt;Kada odabrati ovu arhitekturu?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Ova arhitektura je idealna ako :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Želite da pokrenete brzo (MVP u danima, ne u mesecima)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Očekujete rast složenosti posla&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Želite da smanjite početne troškove&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Виолите PostgreSQL и желите један извор истине.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Волите Kotlin и корутине за пословни код.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Želite da spriječite potpuni vendor lock-in&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ова архитектура НИЈЕ прилагођена ако:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Vaš projekat je jednostavan i ostane Tako (lični blog → 100% Supabase dovoljno)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Već imate uspostavljen backend stek koji kontrolisate&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vi preferiš tradicionalni monolit&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Treba vam .NET, Python ili drugi backend jezik&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_finalna_globalna_vizija&quot;&gt;Finalna globalna vizija&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Potpun hibridna arhitektura&quot; {

  actor &quot;Korisnici&quot; as users

  rectangle &quot;Frontend (statički)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Jednostavni backend (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Poslovni backend (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
Jedinstveni izvor istine&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_najbolje_iz_oba_sveta&quot;&gt;Najbolje iz oba sveta&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova arhitektura vam daje :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 Vločnost Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Покретање у сатима, није у недељама&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;OAuth2 autentifikacija u nekoliko klikova&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Automatski generisani REST API-ji&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Nulta konfiguracija servera&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 моћ Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin и корутине за елегантан асинхронни код&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orchestracija složenih poslovnih procesa&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pouzdani zakazani poslovi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Garantirane ACID transakcije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kompletan ekosistem Spring&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 Progresivna Ekonomija&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ za pokretanje i validiranje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Troškovi koji prate rast&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Не прематурано претерано инжењерство&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 Архитектонска флексибилност&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Progresivna migracija bez preoblikovanja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Додавање Spring Boot само ако је потребно&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Нема укупног зависања од достављача&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Evolutivna arhitektura&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_даље&quot;&gt;Даље&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tehnički_resursi&quot;&gt;Tehnički resursi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Документација Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Упутство за аудентификацију&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Bezbednost na nivou redova&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;Automatski generisani API-ji&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Документација Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot sa Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Korutine i Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT server resursa&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Додатни чланци :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Zaštita API-ja sa JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimizacija performansi PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Uzorci progresivne migracije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Upravljanje greškama u distribuiranoј архитектури&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_реални_случајеви_коришћења&quot;&gt;Реални случајеви коришћења&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova hibridna arhitektura se uspešno koristi u:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;Supabase аутентификација, Spring Boot фактурисање&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tržišta&lt;/strong&gt;: Katalog Supabase, transakcije Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Platforme sadržaja&lt;/strong&gt;: Статеји Supabase, analytics Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Unutrašnji alati&lt;/strong&gt;: CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_чек_лист_за_покретање&quot;&gt;Чек-лист за покретање&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 1 - Osnove (Nedelja 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Kreirati Supabase nalog - [ ] Konfigurisati projekt PostgreSQL - [ ] Omogući Auth (Google, GitHub) - [ ] Definisati početnu šemu - [ ] Konfigurisati Row Level Security - [ ] Testirati API-ove iz JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 2 - MVP (sedmica 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Implementirati glavne stranice - [ ] Интегрирај OAuth2 аутентификацију - [ ] Kreirati obrasce CRUD - [ ] Konfigurisati Storage za datoteke - [ ] Razvrstaj na GitHub stranicama - [ ] Testirati u realnim uslovima&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Faza 3 - evolucija (po potrebi)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifikovati potrebe složene logike - [ ] Креирај пројекат Spring Boot ако је потребно - [ ] Postaviti validaciju JWT Supabase - [ ] Повежи се на PostgreSQL Supabase - [ ] Migrirati kompleksne funkcionalnosti - [ ] Implementirati zakazane poslove - [ ] Деплојовати Spring Boot (Cloud Run, итд.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_antipaterni_obrasci_koje_treba_da_se_izbegnu&quot;&gt;Antipaterni obrasci koje treba da se izbegnu&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ne praviti :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Duplicirati podatke između Supabase i Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kreirati dve odvojene PostgreSQL baze podataka&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kodirajte autentifikaciju sami&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Koristiti Spring Boot za jednostavno CRUD&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Prehitektovanjе od samog početka&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ignorisati Row Level Security Supabase-a&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Радити уместо:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Deliti jedinu PostgreSQL bazu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Neka Supabase rukuje autentifikacijom&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Користити Spring Boot само због сложености&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Početi jednostavno, napredovati postupno&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Iskoristiti snage svake tehnologije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zaštiti na nivou baze podataka pomoću RLS&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_perspektive_evolucije&quot;&gt;Perspektive evolucije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dodavanje_novih_mogućnosti&quot;&gt;Dodavanje novih mogućnosti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Савремена архитектура&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Moguće evolucije&quot; #LightYellow {

  package &quot;Извршност&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;Мониторинг&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;Особности&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_horizontalno_skaliranje&quot;&gt;Horizontalno skaliranje&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kada vaša aplikacija raste, hibridna arhitektura se naturalno skalira :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Автоматски скалирајте до милиона операција&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas za performanse čitanja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Point-in-time recovery за безбедност&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Više instanci iza balančera opterećenja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Bezstanarno projektovanje olakošava horizontalno skaliranje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes za orkestraciju ako je potrebno&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partitioning za velike tabele&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Grupisanje veza (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding ako zapravo neophodan (retko)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arhitektonska_svjedočanstva&quot;&gt;Arhitektonska svjedočanstva&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_korisnika&quot;&gt;Startup SaaS (50k korisnika)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(Empty output) Pokrenuli smo 100% Supabase. Pri 5k korisnika, dodali smo Spring Boot samo za Stripe fakturaciju i mesečne izveštaje. Jedna godina kasnije, 80% naših operacija i dalje prolazi kroz Supabase. Spring Boot upravlja samo kritičnim delom. Ovo razdvajanje nam je omogućilo da skaliramo bez redesigna. &amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_е_лернинг_платформа_10k_корисника&quot;&gt;Е-лернинг платформа (10k корисника)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ OAuth2 autentifikacija Supabase nam je uštedela tri nedelje razvoja. Automatski generisani API-ji upravljaju celim naшим katalogom kursova. Spring Boot služi samo za PDF sertifikate i e-mailove o napretku. Jednostavna, održiva i skalabilna arhitektura. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tržište_b2b_3k_korisnika&quot;&gt;Tržište B2B (3k korisnika)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;__&lt;/em&gt; Spring Boot upravlja transakcijama između kupuvaca i prodavaca (kritično). Supabase upravlja svim ostalim: profili, poruke u realnom vremenu, dokumenti. Fakt da deliju istu PostgreSQL bazu nam sprečava kompleksnu sinhronizaciju. Najbolji arhitektonski izbor koji smo učinili. &amp;lt;/think&amp;gt; &amp;lt;/think&amp;gt; &amp;lt;/think&amp;gt; &amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_синтеза_модерни_архитектонски_парадигма&quot;&gt;Синтеза : модерни архитектонски парадигма&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura Supabase + Spring Boot predstavlja novi paradigam :&lt;strong&gt;arhitektonska specijalizacija&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Stari paradigma&quot; #LightCoral {
  card &quot;Sve u Backendu&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;Нов пародигма&quot; #LightGreen {
  card &quot;Supabase
(Pogodnost)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot\n(Razlikovanje)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Osnovni princip:&lt;/strong&gt;Ne gradite ono što već postoji u obliku usluge. Fokusirajte se na ono što razlikuje vašu aplikaciju.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_правило_8020&quot;&gt;Правило 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U većini aplikacija:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% операција&lt;/strong&gt;su standardni CRUD → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% operacija&lt;/strong&gt;потребна је пословна логика → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo prirodno pravilo objašnjava hibridnu arhitekturu.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;распоређивање операција&quot; {

  rectangle &quot;80% - Standardne operacije&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Poslovna logika&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_konačan_zaključak&quot;&gt;Konačan zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibridna arhitektura nije tehnički kompromis, to je&lt;strong&gt;strategijska odluka&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Omogućava vam da:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Pokreniti brzo sa funkcionalnim MVP-om&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Potvrdite svoje tržište bez teških ulaganja&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Постепено развијај се када сложеност захтева&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Kontroliši svoje troškove u svakom koraku&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Korisiti najbolje od svake tehnologije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Izbegavati prematurno prekomerno inženjerstvo&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Зачувати fleksibilnost za budućnost&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Она представља:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;pragmatizam&lt;/strong&gt;Svaka tehnologija u kojoj izrinjuje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;Brzina&lt;/strong&gt;: minimalno vreme do tržišta&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;Економија&lt;/strong&gt;: Troškovi usklajeni sa vrednošću&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;Скалерност&lt;/strong&gt;Arhitektura koja raste sa vama&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;jačost&lt;/strong&gt;: проверене и pouzdане услуге&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ваш_следећи_корак&quot;&gt;Ваш следећи корак&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ako vam ova arhitektura govori, ovde je gde da počnete :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kreirajte nalog Supabase&lt;/strong&gt;(besplatno)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Определите свој минимална шема података&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Настројите OAuth2 аутентификацију&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Napravite svoju prvu JBake stranicu koja koristi API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Примењите на GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Imat ćete funkcionalni MVP u&lt;strong&gt;неколико дана&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot će se pojaviti prirodno kad ga budete potrebovali. Ne pre toga.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Hibridna arhitektura je umetnost da se konstruiše tačno što je potrebno, kad je potrebno.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Srećan razvoj! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Podijelite ovaj članak ako mislite da može pomoći drugim programerima da donose pravilne arhitekturnе odluke.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

