&lt;li&gt;&lt;a href=&quot;#_шема_вишестепног_логовања&quot;&gt;Шема вишестепног логовања&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dobre_prakse&quot;&gt;Dobre prakse&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_препоручена_структура_логова&quot;&gt;Препоручена структура логова&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_vizuelni_simboli_za_čitljivost&quot;&gt;Vizuelni simboli za čitljivost&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_extrakcija_informacija_iz_izlaza&quot;&gt;Extrakcija informacija iz izlaza&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_пoreђење_препост&quot;&gt;Пoreђење пре/пост&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_pre_problematičan_pristup&quot;&gt;Pre : Problematičan pristup&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_posle_robustni_pristup&quot;&gt;Posle: robustni pristup&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_дијаграм_рекапитулативан&quot;&gt;дијаграм рекапитулативан&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ловце_које_треба_избегати&quot;&gt;Ловце које треба избегати&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_greška_broj_1_zaboraviti_forwardoutput&quot;&gt;Greška broj 1: Zaboraviti `.forwardOutput()&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_засада_број_2_logger_није_иницијализован&quot;&gt;❌ Засада број 2 : Logger није иницијализован&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ловушка_број_3_превише_логирања&quot;&gt;❌ Ловушка број 3 : Превише логирања&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_rezultati_i_metrike&quot;&gt;Rezultati i metrike&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_закључак&quot;&gt;Закључак&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_resursi&quot;&gt;Resursi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_idete_dalje&quot;&gt;Idete dalje&lt;/a&gt;&lt;/li&gt;
