&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_увод&quot;&gt;Увод&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Internacionalizacija (i18n) statičkog sajta može se činiti složeno na prvi pogled, ali JBake u kombinaciji sa Thymeleaf-om nudi elegantna rešenja za kreiranje višezbojnog sajta. U ovom članaku ću vam pokazati kako sam postavio i18n na svom blogu, pokrjujući tako templating i upravljanje člancima na više jezika.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_дијаграм_случајева_коришћења_use_case&quot;&gt;Дијаграм случајева коришћења (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;Аутор&quot; as author
actor &quot;Čitač FR&quot; as reader_fr
actor &quot;Čitač EN&quot; as reader_en

rectangle &quot;сајт JBake вишејезични&quot; {
  usecase &quot;Напиши članak FR&quot; as UC1
  usecase &quot;Написати članak EN&quot; as UC2
  usecase &quot;Konfiguriši i18n poruke&quot; as UC3
  usecase &quot;Генериши сајт&quot; as UC4
  usecase &quot;Pročitaj članak FR&quot; as UC5
  usecase &quot;Прочитај чланак EN&quot; as UC6
  usecase &quot;Promeniti jezik&quot; as UC7
  usecase &quot;Pogledajte dostupne prevodi&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arhitektura_internacionalizacije&quot;&gt;Arhitektura internacionalizacije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naš pristup se zasniva na dva pilija :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;I18n templatinga&lt;/strong&gt;: korišćenje datoteka poruka Thymeleaf za elemente interfejsa&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;I18n sadržaja&lt;/strong&gt;organizacija artikala po jeziku u posebnoj strukturi direktorijuma&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_strukturalni_dijagram_organizacija_fajlova&quot;&gt;Strukturalni dijagram (Organizacija fajlova)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zašto_ovaj_pristup&quot;&gt;Zašto ovaj pristup?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo razdvojenje omogućava:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Одржајте кохерентност у интерфесу без обзира на језик&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Samostalno upravljati sadržajem i prevodima članaka&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Olaksati dodavanje novih jezika bez veće refaktorizacije&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Omogućiti članke dostupne samo na nekim jezicima&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dijagram_komponenti&quot;&gt;Dijagram komponenti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;Izvori&quot; {
  folder &quot;sadržaj/blog/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;en/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;шаблони/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;poruke/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake Engine&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;Generisan sajt&quot; {
  folder &quot;fr/&quot; {
    folder &quot;блог/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;en/&quot; {
    folder &quot;блог/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_templatanja_pomoću_thymeleaf&quot;&gt;I18n templatanja pomoću Thymeleaf&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_фајлова_порука&quot;&gt;Структура фајлова порука&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Prvi korak je da se kreiraju fajlovi svojstva za svaki podržani jezik:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sadržaj_datoteka_poruka&quot;&gt;Sadržaj datoteka poruka&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo je primer datoteke`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;И његов еквивалент на engleskom`messages_en.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_upotreba_u_šablonima&quot;&gt;Upotreba u šablonima&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;У вашим Thymeleaf шаблонима, користите синтаксу`#{}`Za pristup porukama :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_дијаграм_секвенце_решење_i18n&quot;&gt;Дијаграм секвенце - Решење i18n&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc\nParser&quot; as parser
participant &quot;Thymeleaf
Motor&quot; as thymeleaf
participant &quot;I18n\nРешавач&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;Почетна&quot;
i18n --&amp;gt; thymeleaf: &quot;Почетна&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;Početna&quot;
i18n --&amp;gt; thymeleaf: &quot;Početna&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_конфигурација_локале_у_jbake&quot;&gt;Конфигурација локале у JBake&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U vašoj datoteci`jbake.properties`, postavite podrazumevanu lokalu :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_artikala_organizacija_po_direktorijumima&quot;&gt;I18n artikala : organizacija po direktorijumima&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dijagram_toka_flow_generisanje&quot;&gt;Dijagram toka (Flow) - Generisanje&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;За svaku AsciiDoc datoteku&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;Za svaki šablon&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;Filtriranje sadržaja&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_фасцикла&quot;&gt;Структура фасцикла&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Umesto da koristim suffikse u nazivu datoteke, odlučio sam za organizaciju po folderima koja pruža bolju jasnoću i održivost:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_предности_овог_приступа&quot;&gt;Предности овог приступа&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova struktura ima više prednosti:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;jasno odvajanje&lt;/strong&gt;: svaki jezik ima svoj prostor&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;fleksibilno imeovanje&lt;/strong&gt;: datoteke mogu imati različite nazive u zavisnosti od jezika&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Skalabilnost&lt;/strong&gt;: lak je dodati novi jezik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Природна организација&lt;/strong&gt;: prati vremensku logiku JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_metapodaci_članaka&quot;&gt;Metapodaci članaka&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Svaki članak mora sadržavati metapodatke da bi se omogućilo povezivanje između prevoda. Ovo je primer:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Francuska verzija&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Engleska verzija&lt;/strong&gt;(empty)&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;NAPOMENA: Atribut`:jbake-article-id:`је битно : он омогућава везивање различитих превода истог чланка.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_конфигурација_url_ова&quot;&gt;Конфигурација URL-ова&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U`jbake.properties`, podesite uzorak URL-a da uključuje jezik :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo će generisati URL-ove tipa :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_šabloni_za_višejezični_prikaz&quot;&gt;Šabloni za višejezični prikaz&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_шаблон_статье_са_селектором_језика&quot;&gt;Шаблон статье са селектором језика&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Направи шаблон`post.html`ко приказује доступне преводе :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_filtrovan_indeks_po_jeziku&quot;&gt;Filtrovan indeks po jeziku&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kreirajte šablone indeksa za svaki jezik :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(indeks francuski) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(engleski indeks) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_навигација_између_језика&quot;&gt;Навигација између језика&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_globalni_selektor_jezika&quot;&gt;Globalni selektor jezika&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dijagram_toka_čitanje_korisnika&quot;&gt;Dijagram toka - čitanje korisnika&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dodajte selektor jezika u vaš glavni šablon:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_css_stil_za_selektor&quot;&gt;CSS stil za selektor&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_rss_kanal_po_jeziku&quot;&gt;RSS kanal po jeziku&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da biste imali RSS tokove odvojeni po jeziku, kreirajte zasebne šablone :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(francuski tok) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dobre_prakse_i_saveti&quot;&gt;Dobre prakse i saveti&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_konzistentnost_identifikatora_artikla&quot;&gt;1. Konzistentnost identifikatora artikla&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Uverite se da`:jbake-article-id:`je identično za sve prevede od istog članka. Koristite konzistentan format :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Preferirajte engleske identifikatore radi univerzalnosti.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Koristić crtice za razdvajanje reči.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Izbegavajte specijalne karaktere&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_konsekventni_datumi&quot;&gt;2. Konsekventni datumi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sve prevodi jednog članka moraju imati isti datum objave (&lt;code&gt;:jbake-date:&lt;/code&gt;). Ovo olakšava sortiranje i kronološki prikaz.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_višejezični_tagovi&quot;&gt;3. Višejezični tagovi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Za tagove, imate dve opcije:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Опција 1: Универзални тагови на английском&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Опција 2: тагове преведени са мапингом&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_upravljanje_neprevedenim_članacima&quot;&gt;4. Upravljanje neprevedenim članacima&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Nije obavezno prevedati sve članke. Ako članak postoji samo na jednom jeziku, jednostavno neće se pojaviti u popisima drugog jezika.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_višejezična_sitemap&quot;&gt;5. Višejezična sitemap&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Generišite jedan sitemap koji uključuje sve jezike:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak&quot;&gt;Zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Internacionalizacija JBake sajta pomoću Thymeleaf-a je jak i održiv pristup. Odvajanjem i18n od templatinga (putem datoteka poruka) i i18n od sadržaja (putem organizacije u fasciklama), dobijate fleksibilni sistem koji se lako razvija.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Клучне тачке за запамећавање:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Datoteke poruka Thymeleaf&lt;/strong&gt;за кориснички интерфејс&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Organizacija po fasciklima&lt;/strong&gt;(godina/jezik) za članke&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Identifikatori artikla&lt;/strong&gt;повезати преводи&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Посвећени шаблони&lt;/strong&gt;za svaki jezik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Eksplicitni URL-ovi&lt;/strong&gt;uključujući kod jezika&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dijagram_raspoređivanja&quot;&gt;Dijagram raspoređivanja&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;Mašina za razvoj&quot; {
  artifact &quot;Izvor&quot; {
    folder &quot;srećan/&quot;
    folder &quot;šabloni/&quot;
    folder &quot;sredstva/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;Server za izgradnju
(CI/CD)&quot; {
  component &quot;GitHub Actions
ili GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / hosting&quot; {
  node &quot;Statički web server&quot; {
    artifact &quot;Генерисан сајт&quot; {
      folder &quot;/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;Генерисан сајт&quot; : déploiement

actor &quot;Čitaoci&quot; as users

users --&amp;gt; &quot;Statički web server&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova arhitektura vam omogućava da pođete jednostavno sa dva jezika i da dodate još jedan bez velike refaktorisanja. Sve ostaje potpuno statičko i performantno, verno filozofiji JBake.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dobar višijezični razvoj! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_uvod&quot;&gt;Uvod&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_preuzimanje_tor_i_njegovog_potpisa&quot;&gt;Preuzimanje Tor i njegovog potpisa&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_криптографска_провјерка_потписа&quot;&gt;Криптографска провјерка потписа&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_импортирај_јавни_кључ_тор_пројекта&quot;&gt;Импортирај јавни кључ Тор пројекта&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_провери_потпис&quot;&gt;2. Провери потпис&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_praktični_primer_važeći_potpis_ali_nesertifikovan_ključ&quot;&gt;Praktični primer: Važeći potpis ali nesertifikovan ključ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_зашто_проверити_потпис&quot;&gt;Зашто проверити потпис?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ekstrakcija_i_pokretanje_tor_browser&quot;&gt;Ekstrakcija i pokretanje Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_интеграција_на_убунту_десктоп&quot;&gt;Интеграција на Убунту десктоп&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_istraživanje_obrazovnih_resursa_koristeći_tor&quot;&gt;Istraživanje obrazovnih resursa koristeći Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ažuriranje_tor_pretraživača&quot;&gt;Ažuriranje Tor pretraživača&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zaključak&quot;&gt;Zaključak&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_референце&quot;&gt;Референце&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_uvod&quot;&gt;Uvod&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U svetu gde je digitalna privatnost sve više ugrožena, &lt;strong&gt;Tor Browser&lt;/strong&gt; ostaje neophodan alat za čuvanje anonimnosti i slobode informisanja. Međutim, je važno da nikad ne pokrećete preuzeti softver bez da imate&lt;strong&gt;Proverio je njenu autentičnost&lt;/strong&gt;. Ovaj članak predstavlja kompletan metod za:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Preuzeti &lt;strong&gt;Tor Browser&lt;/strong&gt; i njegov potpis`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Проверити валидност преузетог фајла&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Instalirati i pokrenuti &lt;strong&gt;Tor Browser&lt;/strong&gt; na Ubuntu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Dodati ga u menije radne površine za svakodnevno korišćenje&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Istražujte obrazovne i etičke OSINT resurse kroz Tor&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_preuzimanje_tor_i_njegovog_potpisa&quot;&gt;Preuzimanje Tor i njegovog potpisa&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Napravite poseban folder za Tor pretraživač:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zatim preuzmite arhivu pretraživača Tor i njegov potpis :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_криптографска_провјерка_потписа&quot;&gt;Криптографска провјерка потписа&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Овај чекор је&lt;strong&gt;neophodan&lt;/strong&gt;да се осигура да је фајл који је преузет заиста из &lt;strong&gt;Tor Project&lt;/strong&gt;-а и није измењен.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_импортирај_јавни_кључ_тор_пројекта&quot;&gt;Импортирај јавни кључ Тор пројекта&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проверите да је кључ правилно увезен :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_провери_потпис&quot;&gt;2. Провери потпис&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ако је све исправно, ће се приказати следећа порука:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U slučaju upozorenja na nepotpisani ključ, to znači samo da još niste potpisali poverljivi ključ Tor Projecta, ali potpis ostaje važeći.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_praktični_primer_važeći_potpis_ali_nesertifikovan_ključ&quot;&gt;Praktični primer: Važeći potpis ali nesertifikovan ključ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Često je da se naidemo na poruku ovako ova prilikom verifikacije:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova poruka ukazuje da je potpis tehnički &quot;dobar&quot; (datoteka nije izmijenjena), ali vaš GPG sistem ne može &lt;strong&gt;sertifikovati poverenje&lt;/strong&gt; u samu ključ. Da biste razriješili ovo sumnjanje, nužno je uporediti odtisak glavnog ključa (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) са том objavljenom na zvaničnom sajtu Tor Projekta&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Po zvaničnom sajtu, očekivani odtisk prsta je:`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пошто отпечат приказан од`gpg`слага се &lt;strong&gt;истачно&lt;/strong&gt; са кључем са официјалног сајта, можете да будете сигурни да је кључ легитиман и да је датотека сигурна. Упозорење о &quot;несертификованом кључу&quot; онда је информација о вашој локалној GPG конфигурацији, а не о важењу подписа или аудентичности датотеке.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_зашто_проверити_потпис&quot;&gt;Зашто проверити потпис?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Provera GPG potpisa je osnovni čin digitalne bezbednosti. Омогућава:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;garantirati&lt;strong&gt;authentičnost&lt;/strong&gt;preuzetog softvera&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sprečavanje instalacije fajla koji je kompromitovan od strane zlonamernog aktora&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sudjelovati u&lt;strong&gt;digitalna suverenitet&lt;/strong&gt;individualna&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Подстикнути одговорну и етичну цифрову културу&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;Корисник&quot; as U
actor &quot;Server TorProject&quot; as S

usecase &quot;Preuzmi Tor i njegov potpis&quot; as D
usecase &quot;Uvezi javni ključ&quot; as K
usecase &quot;Проверити ГПГ потпис&quot; as V
usecase &quot;Instaliraj i pokreni Tor&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ekstrakcija_i_pokretanje_tor_browser&quot;&gt;Ekstrakcija i pokretanje Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Raspakujte preuzetu arhivu :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zatim pokrenite pregledač :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;При покретању, отвориће се прозор за конфигурацију да се насреди веза са Тор мрежом.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_интеграција_на_убунту_десктоп&quot;&gt;Интеграција на Убунту десктоп&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;За додавање &lt;strong&gt;Tor Browser&lt;/strong&gt; у менију приложения:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zatim możete:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Pokreni &lt;strong&gt;Tor Browser&lt;/strong&gt; iz menija aplikacija&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Додати у омиљенице док&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kreirati prečac sa tastature ako je željeno&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_istraživanje_obrazovnih_resursa_koristeći_tor&quot;&gt;Istraživanje obrazovnih resursa koristeći Tor&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor nije samo alat za anonimnost. Ovo je portal za pristup obrazovnim i istraživačkim resursima, posebno u oblastima:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (Otvoreni izvor informacija)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;edukativno deljenje i otvoren kod&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(pristup kroz Tor za veću privatnost)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(доступан преко Тор)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(pristup slobodnoj naučnoj literaturi)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Prenos znanja i razumevanje čoveka u digitalnom društvu&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Resursi o digitalnoj kulturi, slobodi izražavanja i pristupu znanju&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Slobodna dokumentacija o kiberbezbednosti i etike tehnologije&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ažuriranje_tor_pretraživača&quot;&gt;Ažuriranje Tor pretraživača&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da bi se osigurala optimalna bezbednost, ključno je da &lt;strong&gt;Tor Browser&lt;/strong&gt; ostane ažuriran. Pregledač ima ugrađen mehanizam automatskog ažuriranja koji se može pokrenuti iz komandne linije.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Iz direktorijuma instalacije Tor Browsera, dosta je ponovo pokrenuti skript za pokretanje :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pri pokretanju, &lt;strong&gt;Tor Browser&lt;/strong&gt; će automatski proveriti da li postoji nova verzija. Ako je tako, on će je preuzeti i instalirati za vas.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova jednostavna metoda osigurava da uvek imate najnovija bezbednosna ažuriranja i najnovija unapređenja, što je ključno za bezbednu navigaciju.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak&quot;&gt;Zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Provera vaših preuzimanja je bitna navika za svakoga koji želi da se razvija u bezbednom digitalnom okruženju. Instalirati Tor na proveren način, to je&lt;strong&gt;zaštiti svoj digitalni integritet&lt;/strong&gt;, &lt;strong&gt;сачувати поверенје у слободном софтверу&lt;/strong&gt;, et &lt;strong&gt;јачање његове информационалне аутономије&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Digitalna bezbednost je čin svesti, ne paranoje.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Sintetski pregled upotrebe Tora
actor Utilisateur
rectangle &quot;Tor Browser&quot; {
rectangle &quot;анонимтет&quot; as A
rectangle &quot;Pretraga OSINT&quot; as O
rectangle &quot;Obrazovno deljenje&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_референце&quot;&gt;Референце&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Oficialni sajt Tor Proekta :https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Документација проверке подписаhttps://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Dokumentacija Ubuntu :https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Archive образована :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj članak je deo serije &lt;strong&gt;Sigurnost i digitalna svest&lt;/strong&gt; u cilju promocije odgovornih i pedagoških praksi oko slobodnih alata.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_uvod&quot;&gt;Uvod&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_katalog_verzija_libs_versions_toml_jedno_podsjetanje&quot;&gt;Katalog verzija (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : Jedno podsjetanje&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_problem_jedan_build_kompozitni_i_dva_odvojena_sveta&quot;&gt;2. Problem : Jedan Build Kompozitni i dva odvojena sveta&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_решение_делити_решење_зависности&quot;&gt;3. Решение: Делити решење зависности&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_zaključak_moć_dobro_upravljenih_kompozitnih_gradnje&quot;&gt;4. Zaključak : Moć dobro upravljenih kompozitnih gradnje&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_uvod&quot;&gt;Uvod&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ciljna grupa: Razvojni inženjeri Gradle koji se suočavaju sa upravljanjem zavisnostima u projektima sa više build-ova.&lt;/div&gt;
&lt;p&gt;U našoj potrazi za kreiranjem plugina`site-baker`, smo se trudili da održamo čistu i centralizovanu bazu koda. Jedna od najboljih praksi u modernom Gradle ekosustavu je korištenje&lt;strong&gt;katalog verzija&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) за управљање зависностима. Но шта се дешава када ваш пројекат постаје сложенији, као један&lt;strong&gt;Izgradi kompozit&lt;/strong&gt;Где независни билд (наш плагин) треба да буде укључен у друг ?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tu je naša avantura došla do nezvaničanog obreta. Hteli smo da naš plugin`site-baker`, koji je sam po sebi Gradle projekat, koristi isti katalog verzija kao i naš glavni projekat. Ovaj članak, peti u našoj seriji, opisuje kako smo rešili ovaj izazov.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_katalog_verzija_libs_versions_toml_jedno_podsjetanje&quot;&gt;Katalog verzija (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : Jedno podsjetanje&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Datoteka`gradle/libs.versions.toml`је функционалност Gradle-а која омогућава централизацију верзија и координата зависиености вашег пројекта. Обично је структуриран у четири секcije :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: Definiše alias za brojeve verzija (npr:`kotlin = &quot;1.9.20&quot;`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]&lt;/code&gt;: Дефинише алиаси за потпуне зависносце, коришћењем верзија дефиницисаних изнад (на пример:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]`Skupiti više biblioteka pod jednim pseudinomom (primer:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: Definiše alias za Gradle pluginove.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jednom definisano, Gradle automatski generiše tipizovane pristupnike, što čini vaše`build.gradle.kts`mnogo čitljivije:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Tok podataka iz kataloga verzija&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;Gradle&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;je čitan od&quot;
G --&amp;gt; BuildScript : &quot;generiše akcesor `libs&quot;
BuildScript -&amp;gt; G : &quot;Koristi `libs` za deklarisanje zavisnosti&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_problem_jedan_build_kompozitni_i_dva_odvojena_sveta&quot;&gt;2. Problem : Jedan Build Kompozitni i dva odvojena sveta&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наша структура пројекта је један&lt;strong&gt;Izgradi kompozit&lt;/strong&gt;. Главни пројект (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) uključuje projekat plugina (&lt;code&gt;site-baker&lt;/code&gt;) komandom`includeBuild(&quot;site-baker&quot;)&lt;code&gt;у фајлу`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Struktura kompozitnog građenja&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;Glavni projekt&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;gradle&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;Plugin `site-baker` (Build Uključen)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;site-pekar&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Problem je što je, po defaultu, uključen build jedan&lt;strong&gt;odvojen svet&lt;/strong&gt;. On ima svoju konfiguraciju, svoj životni ciklus, i on ne vidi datoteku`libs.versions.toml`glavnog builda. Naš`plugin/build.gradle.kts`pokušavao je da koristi`libs.plugins.kotlin.jvm`, ali objekat`libs`Nije generisan iz ispravne TOML datoteke, što je izazvalo greške u gradnji.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_решение_делити_решење_зависности&quot;&gt;3. Решение: Делити решење зависности&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Posle nekoliko istraživanja, rešenje se ukazalo kao funkcionalnost Gradle dizajnirana baš za ovaj slučaj :`dependencyResolutionManagement`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;У фајлу`settings.gradle.kts` du &lt;strong&gt;build uključen&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), možemo da Gradle-u kažemo gde da pronađe katalog verzija koje treba da koristimo.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo je konfiguracija koju smo dodali`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Анализирамо критичан део:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)&lt;/code&gt;: Декларишем каталог верзија који ће бити доступан преко алиаса`libs`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))`Ovo je magija. Govorimo Gradle-u da je izvor ovog kataloga datoteka TOML koja se nalazi u direktorijumu.`gradle&lt;/code&gt; du &lt;strong&gt;roditeljski projekat&lt;/strong&gt;(&lt;code&gt;../&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;С овим подешавањем, саграда`site-baker`Сада зна да мора да користи каталог верзија главног пројекта. Објекат`libs`је правилно генерисан, и зависимости су решены као што је планирано.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_zaključak_moć_dobro_upravljenih_kompozitnih_gradnje&quot;&gt;4. Zaključak : Moć dobro upravljenih kompozitnih gradnje&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovo iskustvo je bilo bogato lekcijama. Katalog verzija je fantastičan alat za održavanje, ali ponašanje u scenarijima složenih građenja nije uvek intuitivno.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ključ je da se sećamo da je uključen build i dalje nezavisni build. Da bi se delile konfiguracije, kao što je katalog verzija, potrebno je koristiti eksplicitne mehanizme koje pruža Gradle, kao što je blok`dependencyResolutionManagement`у`settings.gradle.kts`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Rešavanjem ovog problema, nismo samo napravili naš build čistiji, već smo takođe jačili konsistenciju našeg projekta osiguravajući da plugin i glavni projekat dele jedinstveni izvor istine za njihove zavisnosti.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;У следећем чланку, nastavit ćemo da poboljšamo naš plugin dodavanjem složenijih zadataka, sada kada je naše upravljanje zavisnostima čvrsto i centralizovano.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_uvod&quot;&gt;Uvod&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_simptom_neki_fantomski_builds&quot;&gt;Simptom: Neki Fantomski Builds&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_istraživanje_šta_je_keš_konfiguracije&quot;&gt;Istraživanje: Šta je keš konfiguracije ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_причина_проблема_непоглашајући_плагин&quot;&gt;Причина проблема: Непоглашајући плагин&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_временно_решење_ономогући_кеш&quot;&gt;Временно решење: Ономогући кеш&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_истинско_решение_направити_плагин_совместим&quot;&gt;Истинско решение : Направити плагин совместим&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_uvod&quot;&gt;Uvod&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ciljna publika : Gradle programeri koji su već susreli &quot;magična&quot; ili nepredvidljiva ponašanja gradle buildova.&lt;/div&gt;
&lt;p&gt;У нашој авантури креирања плагина`site-baker`, smo sledili rigorozan TDD pristup. Svaka funkcionalnost je bila testirana, validirana, i napredovali smo sa pouzdanjem. I onda je jednog dana neočekivano stigli. Build-ovi su počeli da se ponašaju neravnomerno. Izmene u logici plugina ili u fajlovima konfiguracije su se čile da se ignorišu, i naši funkcioni testovi, koji su bili pouzdani, su počeli da neuspešaju bez razloga.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Posle intenzivne sesije debugovanja, krivac je identifikovan: le&lt;strong&gt;keš konfiguracije Gradle&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_simptom_neki_fantomski_builds&quot;&gt;Simptom: Neki Fantomski Builds&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Problem se manifestovao na nekoliko načina :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Ja sam menjao niz znakova u jednom zadatku`println`, ali stara niza je nastavila da se prikaže tokom izvršavanja.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menjao sam vrednost u svom fajlu`managed-jbake-context.yml`, ali je plugin postupao kao da fajl nije bio promenjen.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Funkcionalni testovi, koji kreiraju test projekte na leto, pađali su jer plugin nije uspeo da otkrije nova kreirana konfiguraciona fajla.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sve se odlagalo kao da Gradle izvršava &quot;fantomsku verziju&quot; našeg builda, ignorirajući naše najnovije izmene.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_istraživanje_šta_je_keš_konfiguracije&quot;&gt;Istraživanje: Šta je keš konfiguracije ?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Keš konfiguracije je relativno moderna i ekstremno moćna funkcija Gradle-ova, aktiviran podrazumevano u novijim verzijama. Njegov cilj je da ubrzade gradnje.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Princip je jednostavan :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;При првом извршавању, Gradle извршава фазу&lt;strong&gt;Конфигурација&lt;/strong&gt;(читање des`build.gradle.kts`, креирање задатака, решавање зависности) и конструише граф задатака.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Na kraju ove faze, Gradle&lt;strong&gt;Серијализује овај граф задатака&lt;/strong&gt;i kešira ga.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tokom sledećih izvršavanja, ako se ništa nije promenilo (skripte za izgradnju,&lt;code&gt;gradle.properties&lt;/code&gt;, itd.), Gradle&lt;strong&gt;Потпуно прескачу фазу конфигурације&lt;/strong&gt;i ponovo koristi keširani graf zadataka.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Mnoštvo uštedjenog vremena je spektakularno na velikim projektima. međutim, ova performans ima svoju cenu: zahteva da se plugins pišu prema strožim pravilima.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Животни циклус кеша конфигурације&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_причина_проблема_непоглашајући_плагин&quot;&gt;Причина проблема: Непоглашајући плагин&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naš plugin`site-baker`kršio, ne znajući, više pravila keša konfiguracije. Da bi graf zadataka bio serijalizabilan, zadaci ne smeju da sadrže reference na složene objekte kao što je objekat`Project`ili čitati fajlove proizvoljno tokom faze izvršenja.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naša glavna greška bila je da smo čitali sadržaj YAML fajla direktno u logiku izvršenja zadatka, koristeći referencu na putanju koja je bila smeštena u našoj ekstenziji. Ovaj pristup je nekompatibilan sa keširanjem jer Gradle ne može da zna da li se sadržaj fajla promenio ako se ovo čitanje ne modelira kao&lt;strong&gt;unos zadatka&lt;/strong&gt;(Task Input).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_временно_решење_ономогући_кеш&quot;&gt;Временно решење: Ономогући кеш&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da bi se otključali i vratili u ponašanje gradnje koje se može predvideti, najbrža rešenje je bilo da se isključi keš konfiguracije. Dovoljno je dodati sledeću liniju u fajl`gradle.properties`projekta koji koristi plugin (ili u našem slučaju, testni projekat)&lt;code&gt;site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Odmah, builds su se vratili na svoje normalno ponašanje. Svako pokretanje je pokrenulo fazu konfiguracije i naše promene su bile uzeti u obzir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Међутим, ово је обходно решење, не трајно решење. Оно жртвује перформансе и не решава основи проблем нашег плагина.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_истинско_решение_направити_плагин_совместим&quot;&gt;Истинско решение : Направити плагин совместим&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da bi plugin bio dobar građanin u modernom Gradle ekosistemu, mora biti kompatibilan sa keširanjem konfiguracije. To podrazumeva ponovo razmišljanje o tome kako podaci težu ka nasim zadacima.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ključ je da se koriste&lt;strong&gt;API‑ji pružatelja&lt;/strong&gt;od Gradle. Umesto prosleđivanja direktnih vrednosti (kao`String` ou un &lt;code&gt;File&lt;/code&gt;) na naše zadatke, moramo provesti`Property&amp;lt;T&amp;gt;`или неке`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ово је план рефакторинга :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Пријавите унос задатака :&lt;/strong&gt;Задатак који анализира YAML датотеку мора да декларише ову датотеку као улаз. За то се користи анотација`@InputFile`.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- @get:InputFile abstract val configFile: RegularFileProperty ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_uvod&quot;&gt;Uvod&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_контекст_наш_плагин_site_baker&quot;&gt;1. Контекст: Наш плагин `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_modelovanje_konfiguracije_u_kotlinu&quot;&gt;2. Modelovanje Konfiguracije u Kotlinu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_интеграција_jackson_a_у_build_gradle_kts&quot;&gt;3. Интеграција Jackson-a у `build.gradle.kts&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tdd_pristup_testiranje_yaml_parsiranja&quot;&gt;4. TDD pristup: Testiranje YAML parsiranja&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_jedinični_test_mapirati_yaml_u_kotlin_objekat&quot;&gt;4.1. Jedinični test : Mapirati YAML u Kotlin objekat&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_funkcionišni_test_provera_čitanja_konfiguracionog_fajla&quot;&gt;4.2. Funkcionišni test : Provera čitanja konfiguracionog fajla&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_vizualizacija_toka_parsiranja&quot;&gt;5. Vizualizacija toka parsiranja&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zaključak&quot;&gt;zaključak&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_uvod&quot;&gt;Uvod&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ciljna grupa: Srednji Gradle programeri koji žele da upravljaju složenim konfiguracijama.&lt;/div&gt;
&lt;p&gt;U razvoju Gradle pluginova, upravljanje složenim konfiguracijama je čežnji zadatak. Umesto da preopterećite DSL stotinama osobina, često je čistije i lakše održivati da se konfiguracija definiše u vanjskom fajlu, kao što je YAML. Ovaj članak vas vodí kroz integraciju moćne Jackson biblioteke za parsiranje YAML fajlova u Kotlin objekte, primenjujući strogu TDD pristup kako bi se osigurala jakost našeg plugina.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_контекст_наш_плагин_site_baker&quot;&gt;1. Контекст: Наш плагин `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naš plugin`site-baker`je namenjen da automatizuje generisanje i implementaciju statičkog sajta. Treba da pročita datoteku konfiguracije YAML (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) za dobijanje informacija kao što su putanje izvora, odredišta deploy-a i Git identifikatori.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;YAML konfiguracija koju želimo da parsiramo glasi ovako:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_modelovanje_konfiguracije_u_kotlinu&quot;&gt;2. Modelovanje Konfiguracije u Kotlinu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пре него што парсирамо, морамо да дефинишемо структуру наших података у Kotlin. Jackson ће ови класе користити за аутоматичко мапирање садржаја YAML.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Funkcija`parseSiteConfiguration`je naša tačka ulaza za deserijalizaciju. Ona koristi`ObjectMapper`de Jackson, konfigurisan sa`YAMLFactory`за YAML format i`registerKotlinModule()`за подршку специфичности Kotlin-а (kao što su podrazumevane vrednosti svojstava)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_интеграција_jackson_a_у_build_gradle_kts&quot;&gt;3. Интеграција Jackson-a у `build.gradle.kts&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da bismo koristili Jackson, moramo da dodamo neophodne zavisnosti u`build.gradle.kts`našeg modula`plugin`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Koristimo`jackson-module-kotlin`за подршку Kotlin и`jackson-dataformat-yaml`за управљање форматом YAML.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tdd_pristup_testiranje_yaml_parsiranja&quot;&gt;4. TDD pristup: Testiranje YAML parsiranja&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sada primenjujemo TDD da bismo validirali našu logiku parsiranja.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_jedinični_test_mapirati_yaml_u_kotlin_objekat&quot;&gt;4.1. Jedinični test : Mapirati YAML u Kotlin objekat&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Počinjemo sa jediničnim testom u`SiteBakerPluginTest.kt`за проверу да функција`parseSiteConfiguration`може правилно претворити YAML низ у објекат`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj test čita sadržaj fajla`managed-jbake-context.yml`(koji mora da postoji da bi test bio važeći) i izvršava tvrdnje na objektu`SiteConfiguration`резултант. Он проверава да ли кључне вредности YAML су правилно пресликане.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_funkcionišni_test_provera_čitanja_konfiguracionog_fajla&quot;&gt;4.2. Funkcionišni test : Provera čitanja konfiguracionog fajla&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Da bismo se uverili da plugin može da pročita fajl konfiguracije kroz svoj DSL i da parsiranje radi u stvarnom Gradle okruženju, dodajemo funkcionalni test u`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Оvaj тест је веома битан јер симулира извршавање додатка у stvarном пројекту. Мора да буде&lt;strong&gt;hermetički&lt;/strong&gt;, to jest da mora sam da kreira fajl`managed-jbake-context.yml`sa kontrolisanim sadržajem, da bi se osigurala ponovljivost i izolacija testa&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj funkcionalni test proverava da li fajl konfiguracije kopiran u privremeni direktorijum testa sadrži ocekivane podatke. Iako ovaj test ne parsira direktno YAML u Kotlin objekat, validira prisustvo fajla i njegovog sadržaja, što je neophodan prethodan korak za parsiranje od strane plugin‑a.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_vizualizacija_toka_parsiranja&quot;&gt;5. Vizualizacija toka parsiranja&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sljedeći dijagram ilustruje tok podataka i interakcije tokom parsiranja YAML konfiguracije:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Корисник Gradle&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;Proširenje sajta&quot; as Extension
participant &quot;managed-bake-context.yml&quot; as ConfigFile
participant &quot;parsirajKonfiguracijuSajta()&quot; as Parser
participant &quot;SiteConfiguration (Kotlin objekat)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak&quot;&gt;zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sledeći TDD pristup, uspešno smo integrirali biblioteku Jackson za parsiranje YAML konfiguracionih fajlova u Kotlin objekte u našem Gradle plug-inu. Ova nam metoda je omogućila:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Modelovati jasno&lt;/strong&gt;naša konfiguracija sa Kotlin data klasama.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Потврдити логику парсинга&lt;/strong&gt;sa ciljnim jediničnim testovima.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Osigurati integraciju&lt;/strong&gt;u realnom Gradle okruženju zahvaljujući hermetičkim funkcionalnim testovima&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova jaka baza nam daje veliko pouzdanje da proširimo naš plugin sa funkcionalnostima koje se baziraju na ovoj konfiguraciji, uz osiguravanje održivosti i jakosti koda. Parsiranje YAML sada je pouzdana i testirana funkcionalnost našeg plugina.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_иницијализација_пројекта&quot;&gt;1. Иницијализација пројекта&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_nas_prvi_tdd_ciklus_unesi_zadatak&quot;&gt;2. Nas prvi TDD ciklus: unesi zadatak&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_први_тест_тест_који_није_успео&quot;&gt;2.1. Први тест (Тест који није успео)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_kod_nakon_uspostavi_test&quot;&gt;2.2. Kod nakon (Uspostavi test)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_drugi_ciklus_tdd_dodati_dsl_ekstenziju&quot;&gt;3. Drugi ciklus TDD: Dodati DSL ekstenziju&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_тест_први&quot;&gt;3.1. Тест први&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_sledeći_kod&quot;&gt;3.2. Sledeći kod&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_funkcionalni_test_validacija_integracije&quot;&gt;4. Funkcionalni test: Validacija integracije&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_test_integracije_kreirati_kontrolisano_okruženje&quot;&gt;4.1. Test integracije: Kreirati kontrolisano okruženje&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_završiti_logiku&quot;&gt;4.2. Završiti logiku&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zaključak&quot;&gt;Zaključak&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U ovom članku bićemo istraživali kako postaviti čvrsto temelj za razvoj Gradle plugina koristeći pristup Test-Driven Development (TDD). Ova metoda nam osigurava da je naš kod robustan, Drživ i tačno odgovara zahtevima od samog početka.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_иницијализација_пројекта&quot;&gt;1. Иницијализација пројекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle olakšava kreiranje novog plugina zahvaljujući naredbi`gradle init`. Izborom da kreiramo &quot;Gradle Plugin&quot; uz Kotlin, dobijamo spremnu strukturu projekta koja uključuje dva ključna tipa testova :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Jedinični testovi :&lt;/strong&gt;položeni u`src/test`, oni omogućavaju validaciju izolovanih komponenti naše dodatka, kao što je interna logika zadatka ili konfiguracija dodatka. Oni su brzi i ne zahtevaju punu izvršavanje Gradle.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Funkcionalni testovi :&lt;/strong&gt;Smješteni u`src/functionalTest`, oni koriste`GradleRunner`Za izvršavanje kompletne Gradle gradnje u privremenom testnom projektu. Ovo nam omogućava da proverimo stvarno ponašanje plugina u kontrolisanom okruženju.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_nas_prvi_tdd_ciklus_unesi_zadatak&quot;&gt;2. Nas prvi TDD ciklus: unesi zadatak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Naša prva zahteva je jednostavna: plugin mora da zabilježi nazvan zadatak`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_први_тест_тест_који_није_успео&quot;&gt;2.1. Први тест (Тест који није успео)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U skladu sa TDD-om, prvo pišemo test koji proverava da li postoji ovaj zadatak. U`SiteBakerPluginTest.kt`(naš fajl za jedinični test), dodajemo :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj test ne uspeva, jer smo još nijedan kod napisali u našem pluginu.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_kod_nakon_uspostavi_test&quot;&gt;2.2. Kod nakon (Uspostavi test)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sada, pišemo minimalno potrebni kod u`SiteBakerPlugin.kt`da bi test prošao :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ponovo pokrećemo testove, i oni prolaze. Naša prva funkcionalnost je validovana.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_drugi_ciklus_tdd_dodati_dsl_ekstenziju&quot;&gt;3. Drugi ciklus TDD: Dodati DSL ekstenziju&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sledeći zahtev je omogućiti korisnicima da konfigurisu naš plugin putem DSL bloka u njihovom`build.gradle.kts`. Želimo blok`site { &amp;#8230;&amp;#8203; }`где може да се наведе путања конфигурације.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_тест_први&quot;&gt;3.1. Тест први&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dodajemo test da proverimo da li je ekstenzija`site`Je dobro evidentirano i možemo joj dodeliti vrednost.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Овај тест не успева ни класа`SiteExtension`ni evidencija ekstenzije ne postoji&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_sledeći_kod&quot;&gt;3.2. Sledeći kod&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kreiramo klasu`SiteBakerExtension.kt`i ažuriramo`SiteBakerPlugin.kt`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Testovi ponovo prolaze.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_funkcionalni_test_validacija_integracije&quot;&gt;4. Funkcionalni test: Validacija integracije&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sada kada su jedinice testirane, moramo se uveriti da sve radi zajedno u stvarnoj gradnji. To je uloga funkcionalnog testa u`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_test_integracije_kreirati_kontrolisano_okruženje&quot;&gt;4.1. Test integracije: Kreirati kontrolisano okruženje&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj test će simulirati pravi projekat koji koristi naš plugin. Da bi bio pouzdan, mora biti&lt;strong&gt;hermetski&lt;/strong&gt;, to jest da ne smije zavisiti od postojećih datoteka na sistemu. On mora sam stvoriti sve neophodne uslove za njegovo izvršenje.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Test će dakle :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Napraviti jedan`build.gradle.kts`test koji koristi naš plugin i njegov DSL.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kreirajte datoteku konfiguracije&lt;/strong&gt;(&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) što plugin treba da pročita. Ovo je ključni korak za robustnost testa.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Izvršiti zadatak`printSiteConfig`преку`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proveri da li je izlaz izgradnje ispravan.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kopirandom ili stvaranjem ove datoteke konfiguracije pri svakom pokretanju, osiguravamo da je test&lt;strong&gt;повторљив&lt;/strong&gt;i ne zavisi od vanjskog stanja. Ovo zaštičava naše testove od regresija koje bi mogle biti povezane sa čitanjem fajla.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj test će neudati dok je zadatak`printSiteConfig`Neće zapravo koristiti vrednost ekstenzije.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_završiti_logiku&quot;&gt;4.2. Završiti logiku&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ažuriramo zadatak u`SiteBakerPlugin.kt`da bi prikazala konfigurisanu vrednost:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Svi testovi, jedinični i funkcionalni, sada prolaze.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zaključak&quot;&gt;Zaključak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sledeći pristup TDD, izgradili smo plugin inkrementalno i bezbedno. Svaka mala funkcionalnost se odmah validira testem, od brzi unitarni testovi do funkcionalnih testova koji validiraju kompletnu integraciju.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pažljivo čineći naše teste funkcionalnim&lt;strong&gt;hermetски&lt;/strong&gt;— naročito programski kreiranjem potrebnih konfiguraционных fajlova — gradimo ekstremno jaku mrežu bezbednosti. Ova riguroznost nam efikasno štiti od regresija i nam daje veliko poverenje da dodajemo složenije funkcionalnosti kasnije, kao što je parsiranje YAML konfiguraционог fajla.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ova čvrsta baza testova je najvažnija vrednost za održavanje i budući razvoj plugin-a.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_увод&quot;&gt;Увод&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_корак_1_покренути_асистент_пројекта&quot;&gt;Корак 1: Покренути асистент пројекта&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_korak_2_razumeti_generisanu_strukturu&quot;&gt;Korak 2: Razumeti generisanu strukturu&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_fajlovi_i_ključni_folderi&quot;&gt;Fajlovi i ključni folderi&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_увод&quot;&gt;Увод&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ciljna grupa: Početni do srednji programer sa Gradle-om.&lt;/div&gt;
&lt;p&gt;Pokretanje novog projekta Gradle dodatka može da izgleda užasno. Na sreću, Gradle pruža moćan interaktivni asistent, zadatak`init`, koji generiše kompletnu, čistu i spremnu strukturu projekta. Ovaj vodič će vam pokazati kako koristiti ovaj alat da kreirate zdravu bazu dodatka, objasniće strukturu i pokazaće vam kako pokrenuti prve zadatke gradnje.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_корак_1_покренути_асистент_пројекта&quot;&gt;Корак 1: Покренути асистент пројекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Komanda`gradle init`Je početna tačka. Ona pokreće komandni asistent koji vam postavlja seriju pitanja za podešavanje projekta.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Otvorite vaš terminal u praznoj mapi i pokrenite :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Asistent će vas voditi. Evo izbora koji treba učiniti za Gradle plugin napisan u Kotlinu:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Izaberite tip projekta za generiranje:&lt;/strong&gt;Izaberite`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Izaberite jezik implementacije:&lt;/strong&gt;Izaberite`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Izaberite DSL za skriptu građenja:&lt;/strong&gt;Изаберите`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Назив пројекта :&lt;/strong&gt;Unesite naziv vašeg projekta (primer:`site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Идентификатор додатка:&lt;/strong&gt;Дайте својој додатку јединствени идентификатор (пример:`com.cheroliv.site-baker`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Plugin klasa:&lt;/strong&gt;Navedite naziv klase implementacije (ex:`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kada se završi, Gradle generira kompletno stablo datoteka.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;дијаграм процеса иницијалисања&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;Gradle plugin&quot;;
:Choisir &quot;Kotlin&quot; (langage);
:Choisir &quot;Kotlin&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_korak_2_razumeti_generisanu_strukturu&quot;&gt;Korak 2: Razumeti generisanu strukturu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Asistent kreira višemodularnu strukturu projekta, odvajajući korenski projekat od izvornog koda plugin-a samog.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fajlovi_i_ključni_folderi&quot;&gt;Fajlovi i ključni folderi&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts`Ovaj fajl u korenu definiše module koji su uključeni u build. Ovde uključe podprojekat.`plugin&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_uvod&quot;&gt;Uvod&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdk_pokretač_gradle&quot;&gt;1. JDK : Pokretač Gradle&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_koja_verzija_da_se_izabere&quot;&gt;Koja verzija da se izabere?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_instalacija_preko_sdkman_preporučeno&quot;&gt;Instalacija preko SDKMAN! (Preporučeno)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instaliraj_sdkman&quot;&gt;&lt;strong&gt;Instaliraj SDKMAN!&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_instalirati_verziju_jdk&quot;&gt;&lt;strong&gt;Instalirati verziju JDK&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_провери_инсталацију&quot;&gt;Провери инсталацију&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ide_intellij_idea&quot;&gt;2. IDE : IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_alat_za_izgradnju&quot;&gt;3. Gradle : alat za izgradnju&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instalacija_putem_sdkman&quot;&gt;Instalacija putem SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instaliraj_gradle&quot;&gt;&lt;strong&gt;Instaliraj Gradle&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_проверити_инсталацију&quot;&gt;Проверити инсталацију&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_generator_statičkog_sajta&quot;&gt;4. JBake : Generator statičkog sajta&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instalacija_putem_sdkman_2&quot;&gt;Instalacija putem SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instaliraj_jbake&quot;&gt;&lt;strong&gt;Instaliraj JBake&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_proveriti_instalaciju&quot;&gt;Proveriti instalaciju&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradle_wrapper_najbolja_praksa&quot;&gt;5. Gradle Wrapper: Najbolja praksa&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_i_portainer_za_ponavljive_gradnje_opciono&quot;&gt;6. Docker i Portainer: Za ponavljive gradnje (opciono)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instalacija_docker_engine&quot;&gt;Instalacija Docker Engine&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_instalirajte_docker_putem_zvaničnog_skripta&quot;&gt;&lt;strong&gt;Instalirajte Docker putem zvaničnog skripta :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_upravljanje_docker_om_bez_sudo_preporučeno&quot;&gt;Upravljanje Docker-om bez &lt;code&gt;sudo&lt;/code&gt; (preporučeno) :&lt;/a&gt;&lt;/li&gt;
