&lt;li&gt;&lt;a href=&quot;#_генерација_pypi_токена&quot;&gt;Генерација PyPI токена&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_skripte_lokalnog_razvoja&quot;&gt;Skripte lokalnog razvoja&lt;/a&gt;
