&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_monitoring_i_observabilnost&quot;&gt;monitoring i observabilnost&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_metrike_pipeline&quot;&gt;Metrike pipeline&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;# .github/workflows/metrics.yml
name: Pipeline Metrics

on:
  workflow_run:
    workflows: [&quot;CI&quot;, &quot;Release&quot;]
    types: [completed]

jobs:
  metrics:
    runs-on: ubuntu-latest
    steps:
    - name: Collect metrics
      run: |
        echo &quot;Pipeline: ${{ github.event.workflow_run.name }}&quot;
        echo &quot;Status: ${{ github.event.workflow_run.conclusion }}&quot;
        echo &quot;Duration: ${{ github.event.workflow_run.updated_at - github.event.workflow_run.created_at }}&quot;
        # Envoyer vers système de monitoring&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_obaveštenja&quot;&gt;Obaveštenja&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;# Ajout dans les workflows pour notifications
- name: Notify on failure
  if: failure()
  uses: 8398a7/action-slack@v3
  with:
    status: failure
    text: &quot;❌ Pipeline failed for ${{ github.repository }}&quot;
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_закључак&quot;&gt;Закључак&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ovaj kompletan CI/CD pipeline za Python nudi :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Potpuna automatizacija&lt;/strong&gt;: od validacije koda do objave&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Безбедност&lt;/strong&gt;automatski skenovi i bezbedno upravljanje tajnostima&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;kvalitet&lt;/strong&gt;: testovi verzija, lintiranje i pokrivenost koda&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Pouzdanost&lt;/strong&gt;: postupno uvođenje putem Test PyPI&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;trazabilnost&lt;/strong&gt;artefakti, izveštaji i izdanja GitHub&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Uvođenje ovih praksi osigurava jak i profesionalan proces isporuke za vaše Python CLI aplikacije, olakšavajući održavanje i razvoj vaših projekata na duži rok.&lt;/p&gt;
&lt;/div&gt;
