&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ find . -name &#39;*.h&#39; -o -name &#39;*.cpp&#39; + +&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
